MOD = 998244353

def main():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    n, m = a[0], a[1]
    at = [[] for _ in range(n + 1)]
    q = 2
    for _ in range(m):
        l, r, x = a[q], a[q + 1], a[q + 2]
        q += 3
        at[l].append((r, x - 1))

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1
    by_r = [0] * (n + 1)

    for left in range(n, 0, -1):
        for right, x in at[left]:
            by_r[right] |= 1 << x
        forbidden = 0
        row = dp[left]
        for right in range(left, n + 1):
            forbidden |= by_r[right]
            length = right - left
            total = 0
            for root in range(left, right + 1):
                if (forbidden & (1 << (root - 1))) == 0:
                    total += (comb[length][root - left] *
                              row[root - 1] * dp[root + 1][right])
            row[right] = total % MOD
    print(dp[1][n])

