import sys
MOD=998244353

def factor(x):
    r = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            r[d] = r.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        r[x] = r.get(x, 0) + 1
    return r

def calc(N, A, p):
    ex = [factor(x).get(p, 0) for x in A]
    R = sum(ex)
    M = N * max(ex, default=0)
    dp = [0] * (R + 1)
    dp[0] = 1
    pp = [1] * (M + 1)
    for i in range(1, M + 1):
        pp[i] = pp[i - 1] * p % MOD
    for t, a in enumerate(ex, 1):
        nd = [0] * (R + 1)
        ds = (0,) if a == 0 else (-a, a)
        for z, w in enumerate(dp):
            if w:
                for d in ds:
                    q = z - d
                    if q >= 0:
                        nd[q] = (nd[q] + w * pp[q]) % MOD
                    else:
                        h = -q
                        nd[0] = (nd[0] + w * pp[h * t]) % MOD
        dp = nd
    return sum(dp) % MOD

data = list(map(int, sys.stdin.buffer.read().split()))
N = data[0]
A = data[1:]
primes = set()
for x in A:
    primes.update(factor(x))
ans = 1
for p in primes:
    ans = ans * calc(N, A, p) % MOD
print(ans)

