import sys

MOD = 998244353
MAXA = 100000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    spf = list(range(MAXA + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for v in range(p * p, MAXA + 1, p):
                if spf[v] == v:
                    spf[v] = p

    phi = list(range(MAXA + 1))
    for p in range(2, MAXA + 1):
        if phi[p] == p:
            for v in range(p, MAXA + 1, p):
                phi[v] -= phi[v] // p

    divisor_cache = {}
    sums = [0] * (MAXA + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        ds = divisor_cache.get(x)
        if ds is None:
            z = x
            factors = []
            while z > 1:
                p = spf[z]
                e = 0
                while z % p == 0:
                    z //= p
                    e += 1
                factors.append((p, e))
            ds = [1]
            for p, e in factors:
                old = ds[:]
                q = 1
                for _ in range(e):
                    q *= p
                    ds += [u * q for u in old]
            divisor_cache[x] = ds

        inc = 0
        for d in ds:
            inc += phi[d] * sums[d]
        answer = (answer * 2 + inc) % MOD
        output.append(str(answer))

        for d in ds:
            v = sums[d] + weight
            if v >= MOD:
                v -= MOD
            sums[d] = v
        weight += weight
        if weight >= MOD:
            weight -= MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

