import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    m = max(a)

    proper_divisors = [[] for _ in range(m + 1)]
    for d in range(1, m + 1):
        for x in range(2 * d, m + 1, d):
            proper_divisors[x].append(d)

    grundy = [0] * (m + 1)
    for x in range(2, m + 1):
        seen = {grundy[d] for d in proper_divisors[x]}
        g = 0
        while g in seen:
            g += 1
        grundy[x] = g

    total = 0
    for x in a:
        total ^= grundy[x]
    print("Anna" if total else "Bruno")


if __name__ == "__main__":
    main()

