import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, q = data[0], data[1]
    parent = list(range(n + 1))
    size = [1] * (n + 1)
    left = list(range(n + 1))
    right = list(range(n + 1))
    color = list(range(n + 1))
    count = [0] * (n + 1)
    for i in range(1, n + 1):
        count[i] = 1

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    ans = []
    pos = 2
    for _ in range(q):
        typ = data[pos]
        pos += 1
        if typ == 1:
            x, c = data[pos], data[pos + 1]
            pos += 2
            root = find(x)
            old = color[root]
            if old != c:
                count[old] -= size[root]
                count[c] += size[root]
                color[root] = c

            if left[root] > 1:
                neighbor = find(left[root] - 1)
                if color[neighbor] == c:
                    root = merge(root, neighbor)
            if right[root] < n:
                neighbor = find(right[root] + 1)
                if color[neighbor] == c:
                    root = merge(root, neighbor)
        else:
            c = data[pos]
            pos += 1
            ans.append(str(count[c]))

    sys.stdout.write("\n".join(ans))

