from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            ending[b].append((a, idx))

        largest = 0
        second = 0
        largest_id = -1
        base = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for a, idx in ending[right]:
                if a > largest:
                    second = largest
                    largest = a
                    largest_id = idx
                elif a > second:
                    second = a

            base += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second

        return base + max(gains)

