class Solution:
    def maxSubarrays(self,n:int,conflictingPairs:List[List[int]])->int:
        at=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y)); at[b].append((a,i))
        top=sec=0; tid=-1
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in at[r]:
                if a>top:
                    sec=top; top=a; tid=i
                elif a>sec:
                    sec=a
            base += r-top
            if tid>=0: gain[tid]+=top-sec
        return base+max(gain)

