import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); m = next(it); q = next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            i = next(it) - 1
            queries.append((1, i))
            closed[i] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (u, v, w) in enumerate(edges):
        if not closed[i]:
            dist[u][v] = w
            dist[v][u] = w

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            di = dist[i]
            dik = di[k]
            if dik == inf:
                continue
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(value if value < inf else -1))
        else:
            u, v, w = edges[query[1]]
            col_u = [dist[i][u] for i in range(n)]
            col_v = [dist[i][v] for i in range(n)]
            row_u = dist[u][:]
            row_v = dist[v][:]
            for i in range(n):
                di = dist[i]
                a = col_u[i]
                b = col_v[i]
                for j in range(n):
                    best = di[j]
                    cand = a + w + row_v[j]
                    if cand < best:
                        best = cand
                    cand = b + w + row_u[j]
                    if cand < best:
                        best = cand
                    di[j] = best

    sys.stdout.write("\n".join(reversed(answers)))

solve()

