from functools import lru_cache
def gen(n,m):
 if n==0: yield (); return
 for x in range(min(n,m),0,-1):
  for q in gen(n-x,x): yield (x,)+q
def main():
 A,B,M=map(int,sys.stdin.readline().split());N=A*B-1;ans=0
 for t in gen(N-A,A):
  if len(t)!=B-1:continue
  L=(A,)+t
  @lru_cache(None)
  def f(s):
   if not s:return 1
   r=0
   for i,x in enumerate(s):
    if i==len(s)-1 or x>s[i+1]:
     z=list(s);z[i]-=1
     if z[i]==0:z.pop(i)
     r+=f(tuple(z))
   return r
  @lru_cache(None)
  def g(s):
   if not s:return 1
   r=0
