class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # dp_less[c] and dp_equal[c] count prefixes with c set bits that
        # are respectively smaller than, or equal to, the prefix of n.
        dp_less = [0] * (length + 1)
        dp_equal = [0] * (length + 1)
        dp_equal[0] = 1

        for ch in s:
            bit = (ch == '1')
            next_less = [0] * (length + 1)
            next_equal = [0] * (length + 1)
            for ones in range(length + 1):
                ways = dp_less[ones]
                if ways:
                    next_less[ones] = (next_less[ones] + ways) % MOD
                    if ones < length:
                        next_less[ones + 1] = (next_less[ones + 1] + ways) % MOD

                ways = dp_equal[ones]
                if ways:
                    if bit:
                        # Put zero here: the resulting number is smaller.
                        next_less[ones] = (next_less[ones] + ways) % MOD
                        if ones < length:
                            next_equal[ones + 1] = (next_equal[ones + 1] + ways) % MOD
                    else:
                        next_equal[ones] = (next_equal[ones] + ways) % MOD
            dp_less, dp_equal = next_less, next_equal

        answer = 0
        for count in range(1, length + 1):
            value = count
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                answer = (answer + dp_less[count]) % MOD
        return answer

