import heapq

def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    INF = 10**9
    d = [[INF] * n for _ in range(n)]
    heap = []
    finite = 0
    maxd = 0
    for i in range(n):
        d[i][i] = 0
        finite += 1
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - 97
                out[i][c].append(j)
                inc[j][c].append(i)
                if d[i][j] == INF:
                    d[i][j] = 1
                    finite += 1
                    heapq.heappush(heap, (1, i, j))
                    maxd = 1
    while heap:
        dist, u, v = heapq.heappop(heap)
        if d[u][v] != dist:
            continue
        nd = dist + 2
        if finite == n * n and nd >= maxd:
            continue
        for c in range(26):
            for a in inc[u][c]:
                row = d[a]
                for b in out[v][c]:
                    if nd < row[b]:
                        if row[b] == INF:
                            finite += 1
                        row[b] = nd
                        if nd > maxd:
                            maxd = nd
                        heapq.heappush(heap, (nd, a, b))
    for row in d:
        print(*(-1 if x == INF else x for x in row))

