from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = factorial[i - 1] * i

        total_odd = (n + 1) // 2
        total_even = n // 2
        used = [False] * (n + 1)
        result = []
        odd_used = 0
        even_used = 0
        last_parity = -1

        for pos in range(n):
            chosen = False
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (last_parity != -1 and parity == last_parity):
                    continue

                remaining_odd = total_odd - odd_used - parity
                remaining_even = total_even - even_used - (1 - parity)
                remaining = n - pos - 1

                if remaining_odd < 0 or remaining_even < 0:
                    count = 0
                elif remaining == 0:
                    count = int(remaining_odd == 0 and remaining_even == 0)
                else:
                    next_parity = 1 - parity
                    needed_odd = ((remaining + 1) // 2
                                  if next_parity == 1 else remaining // 2)
                    needed_even = remaining - needed_odd
                    if (remaining_odd, remaining_even) == (needed_odd, needed_even):
                        count = factorial[remaining_odd] * factorial[remaining_even]
                    else:
                        count = 0

                if k > count:
                    k -= count
                else:
                    used[value] = True
                    result.append(value)
                    odd_used += parity
                    even_used += 1 - parity
                    last_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

