    def largestPalindrome(self, n: int, k: int) -> str:
        if k == 1:
            return '9' * n

        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        half = (n + 1) // 2
        weights = [0] * half
        for i in range(half):
            if i == n - 1 - i:
                weights[i] = powers[i]
            else:
                weights[i] = (powers[i] + powers[n - 1 - i]) % k

        suffix = [None] * (half + 1)
        suffix[half] = bytearray([1] + [0] * (k - 1))
        for i in range(half - 1, -1, -1):
            reachable = bytearray(k)
            next_states = suffix[i + 1]
            weight = weights[i]
            for digit in range(10):
                shift = (digit * weight) % k
                for remainder in range(k):
                    if next_states[remainder]:
                        reachable[(shift + remainder) % k] = 1
