class Solution:
    def countNonDecreasingSubarrays(self, nums, k):
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x
        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)
        edge = [0] * (n + 1)
        for i in range(n):
            q = nxt[i]
            if q < n:
                edge[i] = nums[i] * (q - i) - (pref[q] - pref[i])
        levels = n.bit_length()
        jumps = [nxt + [n]]
        sums = [edge]
        for _ in range(1, levels):
            oj, os = jumps[-1], sums[-1]
            nj = [0] * (n + 1)
            ns = [0] * (n + 1)
            for i in range(n + 1):
                mid = oj[i]
                nj[i] = oj[mid]
                ns[i] = os[i] + os[mid]
            jumps.append(nj)
            sums.append(ns)

        def getcost(left, right):
            p = left
            value = 0
            for z in range(levels - 1, -1, -1):
                q = jumps[z][p]
                if q <= right:
                    value += sums[z][p]
                    p = q
            return value + nums[p] * (right - p + 1) - (pref[right + 1] - pref[p])

        answer = 0
        first = 0
        for right in range(n):
            if getcost(first, right) > k:
                lo, hi = first + 1, right
                while lo < hi:
                    mid = (lo + hi) // 2
                    if getcost(mid, right) <= k:
                        hi = mid
                    else:
                        lo = mid + 1
                first = lo
            answer += right - first + 1
        return answer

