class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        mx = max(cnt)
        candidates = set(range(1, min(mx, 600) + 1))
        for v in cnt:
            for d in range(-3, 4):
                if 1 <= v + d <= mx:
                    candidates.add(v + d)
        candidates.add(mx)
        INF = 10**9
        answer = INF
        for k in candidates:
            dp = [0] + [INF] * k
            for z in cnt:
                suffix = [INF] * (k + 2)
                best = INF
                for q in range(k, -1, -1):
                    best = min(best, dp[q] + q)
                    suffix[q] = best
                prefix = [INF] * (k + 1)
                best = INF
                for q in range(k + 1):
                    best = min(best, dp[q] - q)
                    prefix[q] = best
                nd = [INF] * (k + 1)
                for x in (0, k):
                    for r in range(k + 1):
                        threshold = x + r - z
                        if threshold <= 0:
                            val = suffix[0] + z - x
                        else:
                            val = INF
                            if threshold <= k:
                                val = suffix[threshold] + z - x
                            val = min(val, prefix[min(threshold - 1, k)] + x + 2 * r - z)
                        if val < nd[r]:
                            nd[r] = val
                dp = nd
            answer = min(answer, min(dp[r] + r for r in range(k + 1)))
        return answer

