class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # free[u]: optimum in u's subtree when its parent edge is absent
        # used[u]: optimum when its parent edge is present
        free = [0] * n
        used = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(w + used[v] - free[v])
            gains.sort(reverse=True)

            total = 0
            for gain in gains[:k]:
                if gain > 0:
                    total += gain
            free[u] = base + total

            total = 0
            for gain in gains[:k - 1]:
                if gain > 0:
                    total += gain
            used[u] = base + total

