import sys
from functools import lru_cache

sys.setrecursionlimit(1000000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    k = n + m + l
    full = (1 << k) - 1
    t_initial = (1 << n) - 1
    a_initial = ((1 << m) - 1) << n

    @lru_cache(None)
    def winning(tmask, amask, turn):
        own = tmask if turn == 0 else amask
        if own == 0:
            return False

        table = full ^ tmask ^ amask
        cards = own
        while cards:
            xb = cards & -cards
            cards -= xb
            x = xb.bit_length() - 1

            nt = tmask
            na = amask
            if turn == 0:
                nt ^= xb
            else:
                na ^= xb

            # Play the card and take nothing.
            if not winning(nt, na, turn ^ 1):
                return True

            # Play the card and take any smaller table card.
            candidates = table
            while candidates:
                yb = candidates & -candidates
                candidates -= yb
                y = yb.bit_length() - 1
                if values[y] < values[x]:
                    if turn == 0:
                        nt2, na2 = nt | yb, na
                    else:
                        nt2, na2 = nt, na | yb
                    if not winning(nt2, na2, turn ^ 1):
                        return True

        return False

    print("Takahashi" if winning(t_initial, a_initial, 0) else "Aoki")

