import sys

MOD = 998244353

def solve_case(grid):
    h = len(grid)
    w = len(grid[0])
    col_parity = [0] * w

    for row in grid:
        if sum(c == 'A' for c in row) & 1:
            return 0
        for j, c in enumerate(row):
            col_parity[j] ^= (c == 'A')

    if any(col_parity):
        return 0

    n = h + w
    parent = list(range(n))
    parity = [0] * n

    def find(x):
        if parent[x] != x:
            q = parent[x]
            parent[x] = find(q)
            parity[x] ^= parity[q]
        return parent[x]

    components = n
    for i, row in enumerate(grid):
        row_prefix = 0
        for j, c in enumerate(row):
            if c == 'B':
                a = i
                b = h + j
                required = 1 ^ row_prefix ^ col_parity[j]
                ra = find(a)
                rb = find(b)
                if ra == rb:
                    if parity[a] ^ parity[b] != required:
                        return 0
                else:
                    parent[ra] = rb
                    parity[ra] = parity[a] ^ parity[b] ^ required
                    components -= 1
            row_prefix ^= (c == 'A')

    return pow(2, components, MOD)

