class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        A, B, C = p.split('*')

        def occurrences(t):
            m = len(t)
            pi = [0] * m
            for i in range(1, m):
                k = pi[i - 1]
                while k and t[i] != t[k]:
                    k = pi[k - 1]
                if t[i] == t[k]:
                    k += 1
                pi[i] = k
            result = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != t[k]:
                    k = pi[k - 1]
                if ch == t[k]:
                    k += 1
                if k == m:
                    result.append(i - m + 1)
                    k = pi[k - 1]
            return result

        oa = occurrences(A) if A else []
        ob = occurrences(B) if B else []
        oc = occurrences(C) if C else []
        inf = n + 1

        if A:
            left = [-1] * (n + 1)
            for x in oa:
                left[x + len(A)] = x
            for i in range(1, n + 1):
                left[i] = max(left[i], left[i - 1])

        if C:
            right = [inf] * (n + 1)
            for x in oc:
                right[x] = x
            for i in range(n - 1, -1, -1):
                right[i] = min(right[i], right[i + 1])

        answer = inf
        positions = ob if B else range(n + 1)
        for j in positions:
            end_b = j + len(B)
            start = j if not A else left[j]
            end = end_b if not C else right[end_b] + len(C)
            if start >= 0 and end <= n and start <= end:
                answer = min(answer, end - start)
        return -1 if answer == inf else answer

