from itertools import combinations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    complement = k > n - k
    r = min(k, n - k)
    total = 0
    if complement:
        for v in a:
            total ^= v

    ans = 0
    for chosen in combinations(a, r):
        value = 0
        for v in chosen:
            value ^= v
        if complement:
            value ^= total
        if value > ans:
            ans = value
    print(ans)

