from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Produce the required postorder without recursion.
        stack = [(0, 0)]
        postorder = []
        while stack:
            x, state = stack.pop()
            if state == 0:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
            else:
                postorder.append(x)

        position = [0] * n
        size = [1] * n
        for i, x in enumerate(postorder):
            position[x] = i
            if parent[x] != -1:
                size[parent[x]] += size[x]

        text = ''.join(s[x] for x in postorder)

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i-k] == text[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes.  The center is between i-1 and i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i-k-1] == text[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            r = position[x]
            l = r - size[x] + 1
            length = size[x]
            if length & 1:
                answer[x] = odd[(l + r) // 2] >= length // 2 + 1
            else:
                answer[x] = even[(l + r) // 2 + 1] >= length // 2
        return answer

