from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        if n == 1:
            return max(energyDrinkA[0], energyDrinkB[0])

        # Best totals whose final consumed hour is 0 or 1 respectively.
        a_before = energyDrinkA[0]
        b_before = energyDrinkB[0]
        a_now = max(a_before + energyDrinkA[1], energyDrinkA[1])
        b_now = max(b_before + energyDrinkB[1], energyDrinkB[1])

        for i in range(2, n):
            # To change drinks, the previous hour must be skipped.
            a_next = energyDrinkA[i] + max(a_now, b_before)
            b_next = energyDrinkB[i] + max(b_now, a_before)
            a_before, b_before = a_now, b_now
            a_now, b_now = a_next, b_next

        return max(a_now, b_now)

