class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 1_000_000_007
        # dp[c] is the length produced by one original character c
        # after the transformations performed so far.
        dp = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for c in range(25):
                nxt[c] = dp[c + 1]
            nxt[25] = (dp[0] + dp[1]) % MOD
