import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        prime = [True] * 10000
        prime[0] = prime[1] = False
        for i in range(2, 100):
            if prime[i]:
                for j in range(i * i, 10000, i):
                    prime[j] = False

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            digits = str(value)
            for pos, ch in enumerate(digits):
                digit = ord(ch) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    if pos == 0 and new_digit == 0:
                        continue
                    nxt = int(digits[:pos] + str(new_digit) + digits[pos + 1:])
                    if prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, 10**30):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

