class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        first = [False] * n
        for i in range(1, n):
            first[i] = z[i] >= i

        prev = [0] * (n + 1)
        cur = [0] * (n + 1)
        answer = 0
        for i in range(n - 1, 0, -1):
            prev, cur = cur, prev
            limit = (n + i) // 2
            for j in range(i + 1, limit + 1):
                if nums[i] == nums[j]:
                    cur[j] = 1 + prev[j + 1]
                else:
                    cur[j] = 0
                if cur[j] >= j - i and not (first[i] and j >= 2 * i):
                    answer += 1

        for i in range(1, n):
            if first[i] and 2 * i < n:
                answer += n - 2 * i
        return answer

