class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        initial = s.count('1')
        t = '1' + s + '1'
        best_gain = 0
        i = 0
        n = len(t)

        while i < n:
            if t[i] == '1':
                j = i
                while j < n and t[j] == '1':
                    j += 1

                # This 1-run can be traded only when it has zero-runs
                # on both sides.  Those zero-runs merge after the trade.
                if i > 0 and j < n and t[i - 1] == '0' and t[j] == '0':
                    left = i - 1
                    while left >= 0 and t[left] == '0':
                        left -= 1
                    right = j
                    while right < n and t[right] == '0':
                        right += 1
                    gain = (i - 1 - left) + (right - j)
                    if gain > best_gain:
                        best_gain = gain
                i = j
            else:
                i += 1

        return initial + best_gain

